require_once __DIR__.'/../includes/auth.php'; require_role(['super_admin','manager','receptionist','trainer']); $bid=current_branch_id();$expiryDays=rule_int('expiry_warning_days',7);
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf(); $action=$_POST['action']??'add';
 if($action==='add'){
  require_role(['super_admin','manager','receptionist']);
  $code='FC-'.str_pad((string)random_int(1000,9999),4,'0',STR_PAD_LEFT); $memberEmail=trim($_POST['email']??''); $plan=(int)($_POST['membership_plan_id']??1); $planRow=query_one('SELECT duration_months FROM membership_plans WHERE id=?',[$plan]); $months=(int)($planRow['duration_months']??1); $start=$_POST['membership_start']?:date('Y-m-d'); $end=date('Y-m-d',strtotime("+$months months",strtotime($start)));
  $stmt=db()->prepare("INSERT INTO members(branch_id,member_code,first_name,last_name,email,phone,gender,join_date,membership_plan_id,membership_start,membership_end,status,height_cm,weight_kg,goal,trainer_id,notes) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)");
  $stmt->execute([$bid,$code,trim($_POST['first_name']),trim($_POST['last_name']),$memberEmail,trim($_POST['phone']??''),$_POST['gender']??'Male',$start,$plan,$start,$end,'active',$_POST['height_cm']?:null,$_POST['weight_kg']?:null,trim($_POST['goal']??''),$_POST['trainer_id']?:null,trim($_POST['notes']??'')]);
  $newId=(int)db()->lastInsertId();
  $portalPassword=trim($_POST['portal_password']??'');
  $portalCreated=false;
  if($memberEmail!=='' && $portalPassword!==''){try{db()->prepare('INSERT INTO member_accounts(member_id,email,password,is_active) VALUES(?,?,?,1)')->execute([$newId,$memberEmail,password_hash($portalPassword,PASSWORD_DEFAULT)]);$portalCreated=true;}catch(Throwable $e){}}
  audit_log('member.created','member',$newId,'Member '.$code.' created'.($portalCreated?' with portal account':''));
  flash('success','Member added successfully. Membership ID: '.$code.($portalCreated?' · Member portal activated.':'')); redirect('app/members.php');
 }
 if($action==='delete' && in_array(user()['role'],['super_admin','manager'])){audit_log('member.deleted','member',(int)$_POST['id'],'Member record deleted');db()->prepare('DELETE FROM members WHERE id=? AND branch_id=?')->execute([(int)$_POST['id'],$bid]);flash('success','Member record deleted.');redirect('app/members.php');}
}
$q=trim($_GET['q']??'');$status=$_GET['status']??'';$params=[$bid];$where='m.branch_id=?';if(user()['role']==='trainer'){$myTrainerId=(int)(query_value('SELECT id FROM trainers WHERE user_id=?',[user()['id']])?:0);$where.=' AND m.trainer_id=?';$params[]=$myTrainerId;}if($q!==''){$where.=" AND (m.member_code LIKE ? OR CONCAT(m.first_name,' ',m.last_name) LIKE ? OR m.phone LIKE ?)";$like="%$q%";array_push($params,$like,$like,$like);}if($status!==''){$where.=' AND m.status=?';$params[]=$status;}
$members=query_all("SELECT m.*,p.name plan_name,t.name trainer_name,(SELECT COUNT(*) FROM attendance a WHERE a.member_id=m.id AND a.check_in>=DATE_SUB(NOW(),INTERVAL 30 DAY)) visits30 FROM members m LEFT JOIN membership_plans p ON p.id=m.membership_plan_id LEFT JOIN trainers t ON t.id=m.trainer_id WHERE $where ORDER BY m.created_at DESC",$params);
$plans=query_all("SELECT * FROM membership_plans WHERE status='active' ORDER BY price");$trainers=query_all("SELECT id,name FROM trainers WHERE branch_id=? AND status='active' ORDER BY name",[$bid]);
if(user()['role']==='trainer'){$active=(int)query_value("SELECT COUNT(*) FROM members WHERE branch_id=? AND trainer_id=? AND status='active' AND membership_end>=CURDATE()",[$bid,$myTrainerId]);$expired=(int)query_value("SELECT COUNT(*) FROM members WHERE branch_id=? AND trainer_id=? AND (status='expired' OR membership_end<CURDATE())",[$bid,$myTrainerId]);$due=(int)query_value("SELECT COUNT(*) FROM members WHERE branch_id=? AND trainer_id=? AND status='active' AND membership_end BETWEEN CURDATE() AND DATE_ADD(CURDATE(),INTERVAL $expiryDays DAY)",[$bid,$myTrainerId]);}else{$active=(int)query_value("SELECT COUNT(*) FROM members WHERE branch_id=? AND status='active' AND membership_end>=CURDATE()",[$bid]);$expired=(int)query_value("SELECT COUNT(*) FROM members WHERE branch_id=? AND (status='expired' OR membership_end<CURDATE())",[$bid]);$due=(int)query_value("SELECT COUNT(*) FROM members WHERE branch_id=? AND status='active' AND membership_end BETWEEN CURDATE() AND DATE_ADD(CURDATE(),INTERVAL $expiryDays DAY)",[$bid]);}
$pageTitle='Members'; include __DIR__.'/../includes/header.php'; ?>
<div class="metric-strip"><div class="metric-box"><small>Total members</small><strong><?= count($members) ?></strong></div><div class="metric-box"><small>Active</small><strong><?= $active ?></strong></div><div class="metric-box"><small>Expired</small><strong><?= $expired ?></strong></div><div class="metric-box"><small>Renewal due ≤ <?= $expiryDays ?> days</small><strong><?= $due ?></strong></div></div>
